16	// importedCatalog is the set of NX-03 files the plan imports (30 files): only
17	// what the replay steps use, plus the two pings. It is the REQUIRED set, not the
18	// whole set: a later campaign file (NX-04, NX-05) may sit next to them. The bearer files (two
19	// exchanges), the manifest HEADs (a read through the proxy caches), the
20	// "after-measures" files, the page n1/n2 files and the path/tags files are
21	// deliberately not imported.
22	func importedCatalog() []string {
23		var names []string
24		for _, id := range []string{"admin", "pull", "anon"} {
25			for _, s := range []string{
26				"catalog-group-connector-30482",
27				"catalog-hosted-root-30481",
28				"catalog-hosted-repository",
29				"catalog-proxy-repository",
30				"catalog-group-repository",
31				"rest-repositories-docker-group",
32				"rest-repositories-docker-hosted",
33				"rest-repositories-docker-proxy",
34				"rest-repositories-group-docker-group",
35			} {
36				names = append(names, s+"--"+id)
37			}
38		}
39		names = append(names, "page-group-n1000--admin", "v2-ping-30481--anon", "v2-ping-30482--anon")
40		sort.Strings(names)
41		return names
42	}
