44	func TestLoadCatalogHoldsTheImportedSet(t *testing.T) {
45		fixtures, err := nexusfixture.Load("catalog")
46		if err != nil {
47			t.Fatalf("Load(catalog): %v", err)
48		}
49		if len(importedCatalog()) != 30 {
50			t.Fatalf("test bug: the required set has %d names, the plan says 30", len(importedCatalog()))
51		}
52		byName := map[string]nexusfixture.Fixture{}
53		for i, f := range fixtures {
54			byName[f.Name] = f
55			if i > 0 && fixtures[i-1].Name >= f.Name {
56				t.Errorf("Load(catalog) is not sorted by name: %s then %s", fixtures[i-1].Name, f.Name)
57			}
58			if f.Campaign != "catalog" {
59				t.Errorf("%s: Campaign = %q, want catalog", f.Name, f.Campaign)
60			}
61			// Version, edition and date are what the recorder regenerates: only
62			// their presence is a contract here (the evidence pins the NX-03 values).
63			if f.Meta.NexusVersion == "" || f.Meta.Edition == "" || f.Meta.Measured == "" {
64				t.Errorf("%s: Meta = {%q %q %q}, want a version, an edition and a date", f.Name, f.Meta.NexusVersion, f.Meta.Edition, f.Meta.Measured)
65			}
66			if f.Meta.Record == "pending" {
67				t.Errorf("%s is pending but Load returned it", f.Name)
68			}
69		}
70		for _, name := range importedCatalog() {
71			f, ok := byName[name]
72			if !ok {
73				t.Errorf("Load(catalog) lacks the NX-03 fixture %s", name)
74				continue
75			}
76			if len(f.Exchanges) != 1 {
77				t.Errorf("%s: %d exchanges, want 1 (no multi-exchange file is imported)", f.Name, len(f.Exchanges))
78			}
79		}
80	}
