82	func TestLoadCatalogIdentities(t *testing.T) {
83		fixtures, err := nexusfixture.Load("catalog")
84		if err != nil {
85			t.Fatalf("Load(catalog): %v", err)
86		}
87		counts := map[nexusfixture.Identity]int{}
88		for _, f := range fixtures {
89			counts[f.Identity]++
90			if !strings.HasSuffix(f.Name, "--"+string(f.Identity)) {
91				t.Errorf("%s: Identity = %q, want the file name suffix", f.Name, f.Identity)
92			}
93			if f.Name != f.Scenario+"--"+string(f.Identity) {
94				t.Errorf("%s: Scenario = %q, want the name without the suffix", f.Name, f.Scenario)
95			}
96		}
97		// At least the NX-03 counts (nine scenarios x three, the n1000 page as
98		// admin, two pings as anon): a later file may only add to them.
99		for id, min := range map[nexusfixture.Identity]int{nexusfixture.Admin: 10, nexusfixture.Pull: 9, nexusfixture.Anonymous: 11} {
100			if counts[id] < min {
101				t.Errorf("identity %s has %d fixtures, want at least %d", id, counts[id], min)
102			}
103		}
104	}
