106	func TestLoadedFixturesCarryTheMeasuredFacts(t *testing.T) {
107		// Facts the replay tests of the next steps stand on, read here once on the
108		// loaded set (a regeneration that changed one must be seen).
109		byName := map[string]nexusfixture.Fixture{}
110		fixtures, err := nexusfixture.Load("catalog")
111		if err != nil {
112			t.Fatalf("Load(catalog): %v", err)
113		}
114		for _, f := range fixtures {
115			byName[f.Name] = f
116		}
117		tests := []struct {
118			name       string
119			wantStatus int
120			wantHost   string
121		}{
122			{"rest-repositories-group-docker-group--admin", 200, "127.0.0.1:30481"},
123			{"rest-repositories-group-docker-group--pull", 404, "127.0.0.1:30481"}, // contradiction C1: not 403
124			{"rest-repositories-group-docker-group--anon", 403, "127.0.0.1:30481"},
125			{"catalog-group-connector-30482--admin", 200, "127.0.0.1:30482"},
126			{"catalog-hosted-root-30481--admin", 404, "127.0.0.1:30481"}, // no shared host catalog (IS-07)
127			{"v2-ping-30481--anon", 401, "127.0.0.1:30481"},
128			{"v2-ping-30482--anon", 401, "127.0.0.1:30482"},
129		}
130		for _, tt := range tests {
131			t.Run(tt.name, func(t *testing.T) {
132				f, ok := byName[tt.name]
133				if !ok {
134					t.Fatalf("%s is not loaded", tt.name)
135				}
136				ex := f.Exchanges[0]
137				if ex.Status != tt.wantStatus {
138					t.Errorf("Status = %d, want %d", ex.Status, tt.wantStatus)
139				}
140				if ex.Host != tt.wantHost {
141					t.Errorf("Host = %q, want %q", ex.Host, tt.wantHost)
142				}
143			})
144		}
145		ping := byName["v2-ping-30482--anon"].Exchanges[0]
146		if got := ping.Header.Get("WWW-Authenticate"); !strings.HasPrefix(got, `Bearer realm="http://127.0.0.1:30482/v2/token"`) {
147			t.Errorf("ping WWW-Authenticate = %q, want the Bearer challenge as recorded", got)
148		}
149		// Pinned for the fake server's catalog tolerance (step 3): the DevDesk-shaped
150		// ?n=1000 page and the no-n recording are the same answer on the group connector.
151		n1000 := byName["page-group-n1000--admin"].Exchanges[0]
152		plain := byName["catalog-group-connector-30482--admin"].Exchanges[0]
153		if n1000.Target != "/v2/_catalog?n=1000" || plain.Target != "/v2/_catalog" {
154			t.Errorf("targets = %q and %q, want /v2/_catalog?n=1000 and /v2/_catalog", n1000.Target, plain.Target)
155		}
156	}
