166	func TestCampaignsAndAll(t *testing.T) {
167		campaigns := nexusfixture.Campaigns()
168		if !sort.StringsAreSorted(campaigns) {
169			t.Errorf("Campaigns() = %v, want sorted", campaigns)
170		}
171		if !slices.Contains(campaigns, "catalog") {
172			t.Fatalf("Campaigns() = %v, want it to include catalog", campaigns)
173		}
174		all, err := nexusfixture.All()
175		if err != nil {
176			t.Fatalf("All: %v", err)
177		}
178		var want []nexusfixture.Fixture
179		for _, c := range campaigns {
180			fixtures, err := nexusfixture.Load(c)
