206		if !filepath.IsAbs(dir) || filepath.Base(dir) != "fixtures" {
207			t.Errorf("SourceDir() = %q, want an absolute path ending in fixtures", dir)
208		}
209		want, err := filepath.Abs("fixtures")
210		if err != nil {
211			t.Fatal(err)
212		}
