221	// The contract of SourceDir, which has no argument to vary: it never answers
222	// with a path that is not there. Under -trimpath runtime.Caller gives a path
223	// relative to the module (not absolute, not on disk): SourceDir must then return
224	// an error naming the source tree, not that path. Run with -trimpath to see it.
225	func TestSourceDirIsAnExistingAbsoluteDirectoryOrAnError(t *testing.T) {
226		dir, err := nexusfixture.SourceDir()
227		if err != nil {
228			if dir != "" {
229				t.Errorf("SourceDir() = %q with error %v, want an empty path with an error", dir, err)
230			}
231			if msg := strings.ToLower(err.Error()); !strings.Contains(msg, "source tree") {
232				t.Errorf("error %q must say the source tree cannot be located", err)
233			}
234			return
235		}
236		if !filepath.IsAbs(dir) {
237			t.Errorf("SourceDir() = %q with no error: not an absolute path", dir)
238		}
239		if st, statErr := os.Stat(dir); statErr != nil || !st.IsDir() {
240			t.Errorf("SourceDir() = %q with no error: not an existing directory (%v)", dir, statErr)
241		}
242	}
