269	// Provenance: no hand-written answer can pass as measured. A fixture is either
270	// byte-identical to its dated evidence under docs/measurements/, or it says it
271	// was produced by the recorder.
272	func TestEveryFixtureIsMeasuredOrRecorded(t *testing.T) {
273		fixtures, err := nexusfixture.Load("catalog")
274		if err != nil {
275			t.Fatalf("Load(catalog): %v", err)
276		}
277		for _, f := range fixtures {
278			t.Run(f.Name, func(t *testing.T) {
279				if f.Meta.RecordedBy == "nexus-bench record" {
280					return
281				}
282				if f.Meta.RecordedBy != "" {
283					t.Fatalf("%s: recorded-by = %q, want empty or \"nexus-bench record\"", f.Name, f.Meta.RecordedBy)
284				}
285				evidence, ok := nexusfixture.EvidenceDir(f.Campaign)
286				if !ok {
287					t.Fatalf("%s: campaign %q has no evidence directory and the fixture is not recorded-by nexus-bench record", f.Name, f.Campaign)
288				}
289				want, err := os.ReadFile(filepath.Join("..", "..", filepath.FromSlash(evidence), f.Name+".http"))
290				if err != nil {
291					t.Fatalf("%s: neither recorded-by nexus-bench record nor backed by its evidence: %v", f.Name, err)
292				}
293				if got := nexusfixture.Format(f); string(got) != string(want) {
294					t.Errorf("%s is not byte-identical to %s/%s.http and is not recorded-by nexus-bench record", f.Name, evidence, f.Name)
295				}
296			})
