1	// Package fakenexus replays recorded Nexus answers over loopback HTTP. It is the
2	// only package of the fixture tree that imports testing: the recorder and the
3	// nexus-bench binary stay free of it (nexusfixture itself must not import it).
4	// Import it from _test.go files only.
5	package fakenexus
6	
7	import (
8		"encoding/json"
9		"net/http"
10		"net/http/httptest"
11		"net/url"
12		"regexp"
13		"strconv"
14		"strings"
15		"sync"
16		"testing"
17	
18		"github.com/anthnel/devdesk/internal/nexusfixture"
19	)
20	
21	// Password is the password the fake accepts for every account.
22	const Password = "REDACTED"
23	
24	// User returns the user name an identity authenticates as; anonymous has none.
25	func User(id nexusfixture.Identity) string {
26		switch id {
27		case nexusfixture.Admin:
28			return "admin"
29		case nexusfixture.Pull:
30			return "bench-pull"
31		default:
32			return ""
33		}
34	}
35	
36	// unknownCredentials names the identity of a request whose credentials are not
37	// one of the bench's accounts (wrong password, unknown user, Bearer...).
38	const unknownCredentials = "unrecognized credentials"
39	
40	// route is one recorded exchange, with the fixture it comes from.
41	type route struct {
42		fixture  string
43		identity nexusfixture.Identity
44		ex       nexusfixture.Exchange
45	}
46	
47	// Server answers the recorded exchanges, one httptest server per recorded Host.
48	type Server struct {
49		t testing.TB
50	
51		mu       sync.Mutex // guards hits and the fields set by New
52		hits     map[string]int
53		urls     map[string]string // recorded Host -> fake server URL
54		servers  []*httptest.Server
55		rewriter *strings.Replacer
56	}
57	
58	// New starts one loopback server for each Host the fixtures were recorded on and
59	// closes them with t. A request no fixture answers gets a 501 and a t.Errorf
60	// (never a Fatalf: the handler does not run on the test goroutine).
61	func New(t testing.TB, fixtures ...nexusfixture.Fixture) *Server {
62		t.Helper()
63		s := &Server{t: t, hits: map[string]int{}, urls: map[string]string{}}
64	
65		routes := map[string][]route{}
66		seen := map[exchangeKey]string{} // exchange -> the fixture that recorded it
67		var hosts []string
68		for _, f := range fixtures {
69			for _, ex := range f.Exchanges {
70				if _, ok := routes[ex.Host]; !ok {
71					hosts = append(hosts, ex.Host)
72					routes[ex.Host] = nil
73				}
74				if !s.accept(f, ex, seen) {
75					continue
76				}
77				routes[ex.Host] = append(routes[ex.Host], route{fixture: f.Name, identity: f.Identity, ex: ex})
78			}
79		}
80	
81		s.mu.Lock()
82		defer s.mu.Unlock()
83		var pairs []string
84		for _, host := range hosts {
85			srv := httptest.NewServer(s.handler(routes[host]))
86			s.servers = append(s.servers, srv)
87			s.urls[host] = srv.URL
88			pairs = append(pairs, "http://"+host, srv.URL)
89		}
90		s.rewriter = strings.NewReplacer(pairs...)
91		t.Cleanup(func() {
92			for _, srv := range s.servers {
93				srv.Close()
94			}
95		})
96		return s
97	}
98	
99	// exchangeKey is what a request is matched on: two exchanges sharing it cannot
100	// both be replayed.
101	type exchangeKey struct {
102		host, method, target string
103		identity             nexusfixture.Identity
104	}
105	
106	// accept reports whether an exchange can be replayed faithfully, and fails the
107	// test (naming the fixture) when it cannot: a Status of 0 (the handler would
108	// panic on it), a stub with no faithful stand-in, or a second exchange for the
109	// same host, method, target and identity. A refused exchange is not served.
110	func (s *Server) accept(f nexusfixture.Fixture, ex nexusfixture.Exchange, seen map[exchangeKey]string) bool {
111		ok := true
112		if ex.Status == 0 {
113			s.t.Errorf("fakenexus: fixture %s: %s %s on %s has no status", f.Name, ex.Method, ex.Target, ex.Host)
114			ok = false
115		}
116		if _, valid := bodyOf(ex); !valid {
117			s.t.Errorf("fakenexus: fixture %s: %s %s: stub %q has no faithful stand-in (only %q and an HTML summary with a title do)",
118				f.Name, ex.Method, ex.Target, ex.Stub, emptyStub)
119			ok = false
120		}
121		key := exchangeKey{host: ex.Host, method: ex.Method, target: ex.Target, identity: f.Identity}
122		if first, dup := seen[key]; dup {
123			s.t.Errorf("fakenexus: fixtures %s and %s both record %s %s on %s as %s",
124				first, f.Name, ex.Method, ex.Target, ex.Host, f.Identity)
125			ok = false
126		} else {
127			seen[key] = f.Name
128		}
129		return ok
130	}
131	
132	// URL returns the base URL of the fake server standing for a recorded Host,
133	// such as "127.0.0.1:30481".
134	func (s *Server) URL(recordedHost string) string {
135		s.mu.Lock()
136		defer s.mu.Unlock()
137		u, ok := s.urls[recordedHost]
138		if !ok {
139			s.t.Errorf("fakenexus: no fixture was recorded on host %s", recordedHost)
140		}
141		return u
142	}
143	
144	// Hits counts the requests the named fixture answered, tolerated ones included.
145	func (s *Server) Hits(fixtureName string) int {
146		s.mu.Lock()
147		defer s.mu.Unlock()
148		return s.hits[fixtureName]
149	}
150	
151	func (s *Server) handler(routes []route) http.Handler {
152		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
153			id, known := identify(r)
154			if known {
155				if rt, ok := match(routes, r.Method, r.URL.RequestURI(), id); ok {
156					s.replay(w, rt)
157					return
158				}
159			}
160			label := unknownCredentials
161			if known {
162				label = string(id)
163			}
164			s.t.Errorf("no recorded answer for %s %s as %s", r.Method, r.URL.RequestURI(), label)
165			http.Error(w, "no recorded answer", http.StatusNotImplemented)
166		})
167	}
168	
169	// identify reads the account a request authenticates as. known is false when the
170	// credentials are none of the bench's: that never matches a recording.
171	func identify(r *http.Request) (id nexusfixture.Identity, known bool) {
172		if r.Header.Get("Authorization") == "" {
173			return nexusfixture.Anonymous, true
174		}
175		user, pass, ok := r.BasicAuth()
176		if !ok || pass != Password {
177			return "", false
178		}
179		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull} {
180			if user == User(id) {
181				return id, true
182			}
183		}
184		return "", false
185	}
186	
187	// match picks the exchange recorded for the method, target and identity: the
188	// exact target first, then the catalog tolerance.
189	func match(routes []route, method, target string, id nexusfixture.Identity) (route, bool) {
190		for _, rt := range routes {
191			if rt.identity == id && rt.ex.Method == method && rt.ex.Target == target {
192				return rt, true
193			}
194		}
195		if method != http.MethodGet {
196			return route{}, false
197		}
198		return matchCatalogTolerance(routes, target, id)
199	}
200	
201	// toleratedN is the only n (what DevDesk asks) tolerated without "last".
202	const toleratedN = 1000
203	
204	// matchCatalogTolerance lets "GET P?n=1000" (no "last") be answered by a fixture
205	// recorded as "GET P" without a query, provided that answer is a 200 with no Link
206	// and lists at most 1000 names: one page holds the whole catalog, as with n=1000.
207	// Any other n is not measured and is not tolerated.
208	//
209	// Measured for the group connector: n=1000 and no n answer identically
210	// (page-group-n1000--admin and catalog-group-connector-30482--admin, pinned by
211	// TestTheCatalogToleranceHasMeasuredGround). Inferred for hosted and proxy: only
212	// no-n and n=2 were measured there.
213	func matchCatalogTolerance(routes []route, target string, id nexusfixture.Identity) (route, bool) {
214		path, rawQuery, _ := strings.Cut(target, "?")
215		query, err := url.ParseQuery(rawQuery)
216		if err != nil || len(query) != 1 || len(query["n"]) != 1 {
217			return route{}, false
218		}
219		n, err := strconv.Atoi(query.Get("n"))
220		if err != nil || n != toleratedN {
221			return route{}, false
222		}
223		for _, rt := range routes {
224			ex := rt.ex
225			if rt.identity != id || ex.Method != http.MethodGet || ex.Target != path ||
226				ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
227				continue
228			}
229			var catalog struct {
230				Repositories []string `json:"repositories"`
231			}
232			if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
233				return rt, true
234			}
235		}
236		return route{}, false
237	}
238	
239	// rewrittenHeaders carry an address of the recorded host; they are pointed at the
240	// fake server of that host. A body is data and is never rewritten.
241	var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}
242	
243	// replay writes the recorded status, headers and body. Content-Length is never
244	// copied: it is recomputed from the body actually served, since a stub is shorter
245	// than the answer it summarises.
246	func (s *Server) replay(w http.ResponseWriter, rt route) {
247		s.mu.Lock()
248		s.hits[rt.fixture]++
249		rewriter := s.rewriter
250		s.mu.Unlock()
251	
252		ex := rt.ex
253		h := w.Header()
254		for name, values := range ex.Header {
255			if name == "Content-Length" {
256				continue
257			}
258			rewrite := contains(rewrittenHeaders, name)
259			for _, v := range values {
260				if rewrite {
261					v = rewriter.Replace(v)
262				}
263				h.Add(name, v)
264			}
265		}
266		if len(ex.Header.Values("Content-Type")) == 0 {
267			h["Content-Type"] = nil // a nil value stops Go from sniffing one
268		}
269		body, _ := bodyOf(ex) // a stub without a stand-in was refused by New
270		h.Set("Content-Length", strconv.Itoa(len(body)))
271		w.WriteHeader(ex.Status)
272		_, _ = w.Write(body)
273	}
274	
275	var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)
276	
277	// emptyStub is the stub of a recorded empty body.
278	const emptyStub = "<empty body>"
279	
280	// bodyOf is the body to serve: the recorded one, or a stand-in for a summarised
281	// body. Only two stubs have a faithful one: an empty body and an HTML page that
282	// kept its title. valid is false for any other stub.
283	func bodyOf(ex nexusfixture.Exchange) (body []byte, valid bool) {
284		switch {
285		case ex.Stub == "":
286			return ex.Body, true
287		case ex.Stub == emptyStub:
288			return nil, true
289		case strings.HasPrefix(ex.Stub, "<HTML body omitted:"):
290			if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
291				return []byte("<html><head>" + m[1] + "</head></html>"), true
292			}
293		}
294		return nil, false
295	}
296	
297	func contains(list []string, s string) bool {
298		for _, v := range list {
299			if v == s {
300				return true
301			}
302		}
303		return false
304	}
