213	func (b *recBench) serveListing(repo string, images []ListedImage) {
214		items := []map[string]any{}
215		for _, img := range images {
216			assets := []map[string]any{}
217			if img.Digest != "" {
218				assets = append(assets, map[string]any{
219					"path":     "v2/" + img.Name + "/manifests/" + img.Tag,
220					"checksum": map[string]string{"sha256": strings.TrimPrefix(img.Digest, "sha256:")},
221				})
222			}
223			items = append(items, map[string]any{"name": img.Name, "version": img.Tag, "assets": assets})
224		}
225		body, err := json.Marshal(map[string]any{"items": items, "continuationToken": nil})
226		if err != nil {
227			panic(err)
228		}
229		b.answer("", componentsPath+"?repository="+repo, recAnswer{contentType: "application/json", body: string(body)})
230	}
